// TikTok (Main)
async function tiktok(url) {
  try {
    const data = await _fetchapi('tiktok', url);
    // TikTok data is nested inside 'data.data'
    const tData = data.data; 
    return {
      developer: 'AbroCodes',
      contactme: 'Telegram: abrocodes',
      title: tData?.title,
      author: tData?.author?.nickname,
      cover: tData?.cover,
      play: tData?.play,             // No watermark
      wmplay: tData?.wmplay,         // With watermark
      hdplay: tData?.hdplay,         // HD version
      music: tData?.music_info?.play // Audio link
    };
  } catch (error) {
    return { developer: 'AbroCodes', contactme: 'Telegram: abrocodes', status: false, message: error.message, note: 'Please check the documentation at https://www.npmjs.com/package/ab-downloader' };
  }
}

